svg.script:
function openPage(file) {
  var status = document.getElementById("status");
  if (status) status.textContent = "正在从国内镜像加载…";
  fetch(file, { cache: "reload" }).then(function (res) {
    if (!res.ok) throw new Error(String(res.status));
    return res.text();
  }).then(function (html) {
    if (!html || html.indexOf("<html") === -1) throw new Error("empty");
    var blob = new Blob([html], { type: "text/html;charset=utf-8" });
    location.assign(URL.createObjectURL(blob));
  }).catch(function () {
    if (status) status.textContent = "加载失败。请用系统浏览器重试，或稍等镜像刷新后再开。";
  });
}
document.getElementById("openDash").addEventListener("click", function () { openPage("index.html"); });
openPage("index.html");
